1	package server
2	
3	import (
4		"bytes"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"fmt"
10		"net/http"
11		"net/http/httptest"
12		"strings"
13		"sync"
14		"testing"
15	)
16	
17	func postBody(t *testing.T, h http.Handler, body []byte, contentType string) *httptest.ResponseRecorder {
18		t.Helper()
19		req := httptest.NewRequest(http.MethodPost, "/v1/objects", bytes.NewReader(body))
20		if contentType != "" {
21			req.Header.Set("Content-Type", contentType)
22		}
23		rec := httptest.NewRecorder()
24		h.ServeHTTP(rec, req)
25		return rec
26	}
27	
28	func decodeObjectResponse(t *testing.T, rec *httptest.ResponseRecorder) objectResponse {
29		t.Helper()
30		var resp objectResponse
31		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
32			t.Fatalf("response is not JSON: %v", err)
33		}
34		return resp
35	}
36	
37	// expectedRootCID recomputes the root identifier from the documented
38	// deterministic manifest encoding.
39	func expectedRootCID(size int, cids []string) string {
40		var b strings.Builder
41		fmt.Fprintf(&b, "size:%d\n", size)
42		for _, c := range cids {
43			b.WriteString(c)
44			b.WriteByte('\n')
45		}
46		sum := sha256.Sum256([]byte(b.String()))
47		return "sha256:" + hex.EncodeToString(sum[:])
48	}
49	
50	func TestUploadAndRetrieveRoundTrip(t *testing.T) {
51		h := Handler()
52		payload := make([]byte, ChunkSize*2+123)
53		if _, err := rand.Read(payload); err != nil {
54			t.Fatal(err)
55		}
56	
57		rec := postBody(t, h, payload, "application/octet-stream")
58		if rec.Code != http.StatusCreated {
59			t.Fatalf("status = %d, want %d", rec.Code, http.StatusCreated)
60		}
61		if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
62			t.Fatalf("Content-Type = %q, want application/json", ct)
63		}
64		resp := decodeObjectResponse(t, rec)
65		if resp.Size != len(payload) || resp.ChunkSize != ChunkSize || !resp.Created {
66			t.Fatalf("unexpected response: %+v", resp)
67		}
68		if len(resp.Chunks) != 3 {
69			t.Fatalf("chunks = %d, want 3", len(resp.Chunks))
70		}
71		for i, cid := range resp.Chunks {
72			chunk := payload[i*ChunkSize:]
73			if len(chunk) > ChunkSize {
74				chunk = chunk[:ChunkSize]
75			}
76			sum := sha256.Sum256(chunk)
77			if want := "sha256:" + hex.EncodeToString(sum[:]); cid != want {
78				t.Fatalf("chunk %d cid = %q, want %q", i, cid, want)
79			}
80		}
81		if want := expectedRootCID(len(payload), resp.Chunks); resp.CID != want {
82			t.Fatalf("root cid = %q, want %q", resp.CID, want)
83		}
84	
85		// Byte-identical retrieval.
86		getRec := httptest.NewRecorder()
87		h.ServeHTTP(getRec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+resp.CID, nil))
88		if getRec.Code != http.StatusOK {
89			t.Fatalf("GET status = %d, want %d", getRec.Code, http.StatusOK)
90		}
91		if ct := getRec.Header().Get("Content-Type"); ct != "application/octet-stream" {
92			t.Fatalf("GET Content-Type = %q, want application/octet-stream", ct)
93		}
94		if !bytes.Equal(getRec.Body.Bytes(), payload) {
95			t.Fatal("retrieved bytes differ from uploaded payload")
96		}
97	
98		// Manifest retrieval.
99		manRec := httptest.NewRecorder()
100		h.ServeHTTP(manRec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+resp.CID+"/manifest", nil))
101		if manRec.Code != http.StatusOK {
102			t.Fatalf("manifest status = %d, want %d", manRec.Code, http.StatusOK)
103		}
104		var man manifestResponse
105		if err := json.Unmarshal(manRec.Body.Bytes(), &man); err != nil {
106			t.Fatalf("manifest is not JSON: %v", err)
107		}
108		if man.CID != resp.CID || man.Size != resp.Size || man.ChunkSize != ChunkSize {
109			t.Fatalf("unexpected manifest: %+v", man)
110		}
111		if strings.Join(man.Chunks, ",") != strings.Join(resp.Chunks, ",") {
112			t.Fatalf("manifest chunks differ: %+v", man.Chunks)
113		}
114	}
115	
116	func TestDuplicateUploadReturnsSameCID(t *testing.T) {
117		h := Handler()
118		payload := []byte("hello content addressing")
119	
120		first := decodeObjectResponse(t, postBody(t, h, payload, "application/octet-stream"))
121		if !first.Created {
122			t.Fatal("first upload should report created=true")
123		}
124		rec := postBody(t, h, payload, "application/octet-stream")
125		if rec.Code != http.StatusOK {
126			t.Fatalf("duplicate status = %d, want %d", rec.Code, http.StatusOK)
127		}
128		second := decodeObjectResponse(t, rec)
129		if second.Created {
130			t.Fatal("duplicate upload should report created=false")
131		}
132		if second.CID != first.CID {
133			t.Fatalf("duplicate cid = %q, want %q", second.CID, first.CID)
134		}
135	}
136	
137	func TestDistinctContentYieldsDistinctCID(t *testing.T) {
138		h := Handler()
139		a := decodeObjectResponse(t, postBody(t, h, []byte("aaa"), "application/octet-stream"))
140		b := decodeObjectResponse(t, postBody(t, h, []byte("aab"), "application/octet-stream"))
141		if a.CID == b.CID {
142			t.Fatal("different content produced the same root cid")
143		}
144	}
145	
146	func TestEmptyBodyHasNoChunks(t *testing.T) {
147		h := Handler()
148		rec := postBody(t, h, nil, "application/octet-stream")
149		if rec.Code != http.StatusCreated {
150			t.Fatalf("status = %d, want %d", rec.Code, http.StatusCreated)
151		}
152		resp := decodeObjectResponse(t, rec)
153		if resp.Size != 0 || len(resp.Chunks) != 0 {
154			t.Fatalf("unexpected empty-object response: %+v", resp)
155		}
156		if !strings.Contains(rec.Body.String(), `"chunks":[]`) {
157			t.Fatalf("chunks should encode as [], got %s", rec.Body.String())
158		}
159		if want := expectedRootCID(0, nil); resp.CID != want {
160			t.Fatalf("empty root cid = %q, want %q", resp.CID, want)
161		}
162	}
163	
164	func TestOversizedUploadRejected(t *testing.T) {
165		h := Handler()
166		body := make([]byte, MaxObjectSize+1)
167		rec := postBody(t, h, body, "application/octet-stream")
168		if rec.Code != http.StatusRequestEntityTooLarge {
169			t.Fatalf("status = %d, want %d", rec.Code, http.StatusRequestEntityTooLarge)
170		}
171		assertErrorCode(t, rec, "payload_too_large")
172	
173		// The oversized attempt must not leave a partial object behind.
174		manRec := httptest.NewRecorder()
175		h.ServeHTTP(manRec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+expectedRootCID(0, nil)+"/manifest", nil))
176		if manRec.Code != http.StatusNotFound {
177			t.Fatalf("store should be empty after rejected upload, got %d", manRec.Code)
178		}
179	}
180	
181	func TestExactMaxSizeAccepted(t *testing.T) {
182		h := Handler()
183		body := make([]byte, MaxObjectSize)
184		rec := postBody(t, h, body, "application/octet-stream")
185		if rec.Code != http.StatusCreated {
186			t.Fatalf("status = %d, want %d", rec.Code, http.StatusCreated)
187		}
188		resp := decodeObjectResponse(t, rec)
189		if len(resp.Chunks) != MaxObjectSize/ChunkSize {
190			t.Fatalf("chunks = %d, want %d", len(resp.Chunks), MaxObjectSize/ChunkSize)
191		}
192	}
193	
194	func TestWrongMediaTypeRejected(t *testing.T) {
195		h := Handler()
196		for _, ct := range []string{"text/plain", "application/json", ""} {
