    delete(s.pins, cid)
    return true
}

// pinEntry is one live pin in listing order.
type pinEntry struct {
    cid       string
    expiresAt *time.Time
}

// listPins returns the valid pins sorted by cid.
func (s *store) listPins(now time.Time) []pinEntry {
    s.mu.RLock()
    defer s.mu.RUnlock()
    entries := []pinEntry{}
    for cid, p := range s.pins {
