    sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
    return entries
}

// collectGarbage removes (or, when dryRun, only counts) objects with no valid
// pin in force at now. It returns the affected cids in lexical order and the
// sum of their body sizes.
func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, bytes int) {
    s.mu.Lock()
    defer s.mu.Unlock()
    cids = []string{}
    for cid, p := range s.pins {
        if !validPin(p, now) {
            delete(s.pins, cid)
        }
    }
    for cid, obj := range s.objects {
        if _, pinned := s.pins[cid]; pinned {
            continue
